return {api_version=1,id="EX1_564",name="Faceless Manipulator",text="<b>Battlecry:</b> Choose a minion and become a copy of it.",set="EXPERT1",type="minion",rarity="epic",cost=5,attack=3,health=3,keywords={"battlecry"},target_mode="required_if_available",targets=function(ctx,self)local r={};for _,e in ipairs(ctx:minions())do if e~=self then r[#r+1]=e end end;return r end,on_battlecry=function(ctx,self,target)if target then ctx:transform_into_copy(self,target)end end}
